settings.custom_liquid:
{%- comment -%} CHỈ CHẠY CODE NÀY TẠI TRANG CHỦ VÀ KHI KHÁCH CHƯA ĐĂNG NHẬP {%- endcomment -%}
{%- if template == 'index' and customer == nil -%}
<div id="paw-popup-overlay" style="display:none;">
  <div class="paw-popup-window">
    <button class="paw-close" onclick="closePawPopup()">×</button>

    <div class="paw-content-wrapper">
      <div class="paw-image-side">
        <img src="https://cdn.shopify.com/s/files/1/0659/7217/5054/files/4_cc00057e-52ad-4897-bca6-b9f4f99eccef.webp?v=1764268001" alt="PawUnder Dog">
      </div>

      <div class="paw-form-side">
        <img src="https://cdn.shopify.com/s/files/1/0659/7217/5054/files/logo-pawunder-black.png?v=1775698434" class="paw-logo" alt="Logo">

        {% form 'customer', id: 'paw-email-form' %}
          <input type="hidden" name="contact[tags]" value="newsletter">

          {%- if form.posted_successfully? -%}
            {%- comment -%} GIAO DIỆN CHÀO MỪNG SAU KHI SUBMIT {%- endcomment -%}
            <div class="paw-success-container">
               <div style="font-size: 40px; margin-bottom: 10px;">🐾</div>
               <h2>Welcome to PawUnder family!</h2>
               <p>Your subscription was successful. Check your inbox (or spam folder) for your <strong>10% OFF</strong> discount code!</p>
               <button type="button" class="paw-submit" style="margin-top: 20px;" onclick="closePawPopup()">Start Shopping</button>
            </div>
            <script>
              localStorage.setItem('paw_popup_submitted', 'true');
            </script>
          {%- else -%}
            {%- comment -%} GIAO DIỆN NHẬP EMAIL BAN ĐẦU {%- endcomment -%}
            <h2>Get 10% OFF Your First Order</h2>
            <p>Sign up now and get an extra <strong>10% OFF</strong> your order, plus exclusive pet deals delivered straight to your inbox.</p>

            <div style="margin-top: 20px;">
              <input type="email" name="contact[email]" placeholder="Enter Your Email" required style="width: 100%; padding: 12px; margin-bottom: 10px; border: 1px solid #ccc; border-radius: 5px;">
              <button type="submit" class="paw-submit">Subscribe</button>
            </div>

            <p class="paw-tip">Tip: You always get <strong>FREE expedited shipping</strong> from PawUnder</p>
          {%- endif -%}
        {% endform %}
      </div>
    </div>
  </div>
</div>

<style>
  #paw-popup-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.7); z-index: 10000; display: flex; align-items: center; justify-content: center; }
  .paw-popup-window { background: #fff; width: 850px; max-width: 95%; position: relative; border-radius: 10px; overflow: hidden; }
  .paw-content-wrapper { display: flex; min-height: 450px; }
  .paw-image-side { width: 45%; }
  .paw-image-side img { width: 100%; height: 100%; object-fit: cover; display: block; }
  .paw-form-side { width: 55%; padding: 40px; text-align: center; display: flex; flex-direction: column; justify-content: center; }
  .paw-logo { width: 140px; margin: 0 auto 20px; }
  .paw-form-side h2 { font-size: 26px; margin-bottom: 15px; font-weight: bold; color: #000; line-height: 1.2; }
  .paw-form-side p { font-size: 15px; line-height: 1.5; color: #333; margin: 0; }
  .paw-tip { font-size: 12px !important; color: #888 !important; margin-top: 15px !important; }
  .paw-submit { width: 100%; padding: 14px; background: #ff8a00; color: #fff; border: none; border-radius: 30px; font-weight: bold; cursor: pointer; font-size: 16px; transition: background 0.3s; }
  .paw-submit:hover { background: #e67c00; }
  .paw-close { position: absolute; top: 10px; right: 15px; font-size: 30px; border: none; background: none; cursor: pointer; color: #aaa; z-index: 10; line-height: 1; }
  .paw-success-container h2 { color: #2d8a2d; }
  @media (max-width: 768px) { .paw-image-side { display: none; } .paw-form-side { width: 100%; padding: 30px 20px; } }
</style>

<script>
  function closePawPopup() { 
    document.getElementById('paw-popup-overlay').style.display = 'none'; 
  }

  function initPawPopup() {
    const isSubmitted = localStorage.getItem('paw_popup_submitted');
    const urlParams = new URLSearchParams(window.location.search);
    const hasPosted = urlParams.has('customer_posted');

    // 1. Nếu vừa nhấn Subscribe xong (trang load lại có params) -> Hiện ngay lập tức để thấy Success Message
    if (hasPosted) {
      document.getElementById('paw-popup-overlay').style.display = 'flex';
      return;
    }

    // 2. Nếu chưa từng submit và không có params -> Hiện sau 3 giây
    if (!isSubmitted) {
      setTimeout(() => { 
        if(document.getElementById('paw-popup-overlay')) {
          document.getElementById('paw-popup-overlay').style.display = 'flex'; 
        }
      }, 3000);
    }
  }

  document.addEventListener('DOMContentLoaded', initPawPopup);
</script>
{%- endif -%}
